fn parse_args(args: Vec<String>) -> Result<(Options, Vec<String>), ParseError> {
    let mut options = Options::defaults();
    let mut positional = Vec::new();
    let mut seen_unknown: HashMap<String, bool> = HashMap::new();
    let mut i = 0;
    while i < args.len() {
        let arg = &args[i];
        if !is_option(arg) { positional.push(arg.clone()); i += 1; continue; }
        let (name, attached) = match arg.split_once('=') { Some((a,b)) => (a, Some(b.to_owned())), None => (arg.as_str(), None) };
        if name == "--help" || name == "-h" { return Err(ParseError { code: 0, message: help_text() }); }
        if name == "--version" { return Err(ParseError { code: 0, message: version_text() }); }
        let known = known_option(name);
        if let Some((key, kind)) = known {
            match kind {
                Kind::Flag => {
                    let value = if name.starts_with("--no-") { false } else if let Some(v) = attached { v == "1" } else { true };
                    options.set(key, Value::Bool(value), false);
                }
                Kind::Value | Kind::List => {
                    let value = take_value(attached, &args, &mut i).ok_or_else(|| missing_value(key))?;
                    let parsed = process_known(key, value)?;
                    options.set(key, parsed, matches!(kind, Kind::List));
                }
            }
        } else {
            let key = name.trim_start_matches('-').strip_prefix("no-").unwrap_or(name.trim_start_matches('-')).to_owned();
            let repeated = seen_unknown.contains_key(&key);
            let next_is_option = args.get(i + 1).map(|s| is_option(s)).unwrap_or(false);
            if attached.is_none() && !repeated && next_is_option {
                options.set(&key, Value::Bool(true), false);
            } else {
                let value = take_value(attached, &args, &mut i).ok_or_else(|| ParseError { code: 1, message: format!("Missing value: --{} requires a value\n\n---\n\n{}", key, help_text()) })?;
                options.set(&key, parse_custom(&value), repeated);
            }
            seen_unknown.insert(key, true);
        }
        i += 1;
    }
    if !["babel", "babylon", "flow", "ts", "tsx"].contains(&options.parser.as_str()) {
        return Err(ParseError { code: 1, message: format!("Error: --parser must be one of the values babel,babylon,flow,ts,tsx\n\n---\n\n{}", help_text()) });
    }
    if ![0,1,2].contains(&options.verbose) {
        return Err(ParseError { code: 1, message: format!("Error: --verbose must be one of the values 0,1,2\n\n---\n\n{}", help_text()) });
    }
    Ok((options, positional))
}

