fn discover(path: &Path, extensions: &[String], patterns: &[String], out: &mut Vec<String>) {
    let metadata = match fs::symlink_metadata(path) { Ok(v)=>v, Err(_)=>{ eprintln!("Skipping path {} which does not exist. ", path.display()); return; } };
    if metadata.is_dir() {
        let entries = match fs::read_dir(path) { Ok(v)=>v, Err(e)=>panic!("{}", e) };
        for entry in entries {
            let entry = match entry { Ok(v)=>v, Err(_)=>continue }; let child = entry.path();
            if should_ignore(&child, patterns) { continue; }
            match fs::metadata(&child) {
                Ok(m) if m.is_dir() => discover(&child, extensions, patterns, out),
                Ok(_) => if extension_matches(&child, extensions) { out.push(child.to_string_lossy().into_owned()); },
                Err(_) => println!("Skipping path \"{}\" which does not exist.", child.display()),
            }
        }
    } else if extension_matches(path, extensions) && !should_ignore(path, patterns) { out.push(path.to_string_lossy().into_owned()); }
}
