{"command":"create","path":"/workspace/codebase/bridge/transform-host.js","file_text":"#!/usr/bin/env node
'use strict';

const fs = require('fs');
const http = require('http');
const https = require('https');

function encode(value) {
  return Buffer.from(value == null ? '' : String(value)).toString('base64');
}

function event(fields) {
  process.stdout.write(fields.join('\t') + '\n');
}

function getParser(name, options) {
  return require('../src/getParser')(name, options);
}

function loadTransform(filename, useBabel) {
  if (useBabel) {
    const {DEFAULT_EXTENSIONS} = require('@babel/core');
    const presets = [];
    try {
      const presetEnv = require('@babel/preset-env');
      presets.push([presetEnv.default, {targets: {node: true}}]);
    } catch (_) {}
    presets.push(
      /\.tsx?$/.test(filename)
        ? require('@babel/preset-typescript').default
        : require('@babel/preset-flow').default
    );
    require('@babel/register')({
      configFile: false,
      babelrc: false,
      presets,
      plugins: [
        require('@babel/plugin-transform-class-properties').default,
        require('@babel/plugin-transform-nullish-coalescing-operator').default,
        require('@babel/plugin-transform-optional-chaining').default,
        require('@babel/plugin-transform-modules-commonjs').default,
        require('@babel/plugin-transform-private-methods').default,
      ],
      extensions: [...DEFAULT_EXTENSIONS, '.ts', '.tsx'],
      ignore: [/@babel\/parser/, /\/flow-parser\//, /\/recast\//, /\/ast-types\//],
    });
  }
  const loaded = require(filename);
  return {
    transform: typeof loaded.default === 'function' ? loaded.default : loaded,
    parser: loaded.parser,
  };
}

function cleanStack(error) {
  if (!error || !error.stack) return '';
  const lines = error.stack.split('\n');
  const result = [];
  lines.every(line => {
    if (line.includes(__filename)) return false;
    result.push(line);
    return true;
  });
  return result.join('\n');
}

async function run() {
  let input = '';
  for await (const chunk of process.stdin) input += chunk;
  const request = JSON.parse(input);
  const loaded = loadTransform(request.transform, request.babel);
  const core = require('../src/core');
  let parserFromTransform;
  if (loaded.parser) {
    parserFromTransform = typeof loaded.parser === 'string'
      ? getParser(loaded.parser)
      : loaded.parser;
  }

  for (const file of request.files) {
    let source;
    try {
      source = await fs.promises.readFile(file, 'utf8');
    } catch (error) {
      event(['S', 'error', encode(file), encode('File error: ' + error), '']);
      continue;
    }
    try {
      const parser = parserFromTransform || getParser(
        request.options.parser,
        request.options.parserConfig
      );
      const jscodeshift = core.withParser(parser);
      const api = {
        j: jscodeshift,
        jscodeshift,
        stats(name, quantity) {
          if (!request.options.dry) return;
          event(['U', encode(name), typeof quantity === 'number' ? quantity : 1]);
        },
        report(message) {
          event(['R', encode(file), encode(message)]);
        },
      };
      const output = await loaded.transform(
        {path: file, source},
        api,
        request.options
      );
      if (!output || output === source) {
        event(['S', output ? 'nochange' : 'skip', encode(file), '', '']);
      } else {
        const bytes = Buffer.isBuffer(output) ? output : Buffer.from(String(output));
        event(['S', 'ok', encode(file), '', bytes.toString('base64')]);
      }
    } catch (error) {
      const message = 'Transformation error (' + String(error.message).replace(/\n/g, ' ') + ')\n' + cleanStack(error);
      event(['S', 'error', encode(file), encode(message), '']);
    }
  }
}

function download(url, destination) {
  const client = url.startsWith('https') ? https : http;
  client.get(url, response => {
    let body = '';
    response.on('data', chunk => { body += chunk.toString(); });
    response.on('end', () => fs.writeFileSync(destination, body));
  }).on('error', error => {
    console.error(error);
    process.exitCode = 1;
  });
}

if (process.argv[2] === 'download') {
  download(process.argv[3], process.argv[4]);
} else {
  run().catch(error => {
    console.error(error && error.stack || error);
    process.exitCode = 1;
  });
}
"}

